def table(frame):
 if frame.empty:return '충분한 유효 관측이 없음'
 cols=list(frame.columns);rows=['| '+' | '.join(cols)+' |','| '+' | '.join('---' for _ in cols)+' |']
 for row in frame.itertuples(index=False,name=None):rows.append('| '+' | '.join(f'{v:.4f}' if isinstance(v,float) else str(v) for v in row)+' |')
 return '\n'.join(rows)
# Descriptive distributions and paired comparison figures.
fig,axes=plt.subplots(1,3,figsize=(17,4));counts=df.background_type.value_counts();axes[0].bar(counts.index,counts.values);axes[0].set(title='Inferred background types',ylabel='Images')
for status,part in accepted.groupby('status'):axes[1].hist(part.product_mean,bins=np.linspace(0,256,33),density=True,alpha=.5,label=status)
axes[1].set(title='Accepted subset: product brightness',xlabel='Mean grayscale [0,255]',ylabel='Density');axes[1].legend()
valid=comparison.dropna(subset=['whole_paired_difference','product_difference']);comparison['sign_changed']=comparison.whole_paired_difference*comparison.product_difference<0;comparison['selection_effect_on_whole_difference']=comparison.whole_paired_difference-comparison.whole_all_difference;comparison['region_effect_on_paired_difference']=comparison.product_difference-comparison.whole_paired_difference;comparison.to_csv(out/'brightness_interpretation_changes.csv',index=False);axes[2].scatter(valid.whole_paired_difference,valid.product_difference,s=12,alpha=.5);axes[2].axhline(0,color='gray');axes[2].axvline(0,color='gray');axes[2].set(title='Same accepted images: NG minus OK',xlabel='Whole-image mean difference',ylabel='Product-region mean difference');fig.tight_layout();fig.savefig(out/'regional_brightness_overview.png',dpi=130);plt.close(fig)
status_table=df.groupby(['category','segmentation_status']).size().unstack(fill_value=0);status_table['total']=status_table.sum(axis=1);status_table['accepted_fraction']=status_table.get('accepted_heuristic',0)/status_table.total;status_table.to_csv(out/'segmentation_selection_by_category.csv')
selection=df.groupby(['segmentation_status','status']).whole_mean.agg(['count','mean','std','median']).reset_index();selection.to_csv(out/'segmentation_selection_brightness.csv',index=False)
